/* ----------------------------------------------------------------------------
   Shared helpers (appended by the build). Pure functions — safe anywhere.
---------------------------------------------------------------------------- */
window.ArticleUtils = {
  sorted() {
    return [...window.ARTICLES].sort((a, b) => b.date.localeCompare(a.date));
  },
  bySlug(slug) {
    return window.ARTICLES.find((a) => a.slug === slug) || null;
  },
  allTags() {
    const seen = [];
    window.ArticleUtils.sorted().forEach((a) =>
      a.tags.forEach((t) => { if (!seen.includes(t)) seen.push(t); })
    );
    return ["ALL", ...seen];
  },
  related(slug, limit = 2) {
    const self = window.ArticleUtils.bySlug(slug);
    if (!self) return [];
    return window.ArticleUtils.sorted()
      .filter((a) => a.slug !== slug)
      .map((a) => ({ a, score: a.tags.filter((t) => self.tags.includes(t)).length }))
      .sort((x, y) => y.score - x.score)
      .slice(0, limit)
      .map((x) => x.a);
  },
  prettyDate(iso) {
    const d = new Date(iso + "T00:00:00");
    return d.toLocaleDateString("en-AU", { day: "numeric", month: "short", year: "numeric" });
  },
  readingTime(article, wordCount) {
    if (article && article.readMins) return article.readMins;
    if (!wordCount) return null;
    return Math.max(1, Math.round(wordCount / 220));
  },
};
